class Solution:
    def minNumberOfSemesters(self, n: int, relations: List[List[int]], k: int) -> int:
        INF = float('inf')
        pre = [0] * n
        for a, b in relations:
            pre[b - 1] |= 1 << (a - 1)
        full = (1 << n) - 1
        dp = [INF] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            if dp[mask] == INF:
                continue
            avail = 0
            for i in range(n):
                if not (mask >> i & 1) and pre[i] & mask == pre[i]:
                    avail |= 1 << i
            sub = avail
            while sub:
                if bin(sub).count('1') <= k:
                    nm = mask | sub
                    if dp[mask] + 1 < dp[nm]:
                        dp[nm] = dp[mask] + 1
                sub = (sub - 1) & avail
        return dp[full]

